#[test] fn bm15_live_and_success_reuse(){let _b=Bounds::new();fixture(true,None,|p|{push(p,&[Value::I32(0),Value::I32(0),Value::I32(1)]);p.phase.operation.control.remove_live(Live::Values,1).unwrap();let before=observed(p);assert_eq!(op(p,COPY).unwrap_err().code,"swift_frame_live_mismatch");assert_eq!(observed(p).execution_work,before.execution_work);assert_eq!(p.phase.parts.values.len(),3);});fixture(true,None,|p|{let mut s=storage();p.bulk_memory_operation(SIZE,&mut s.entry).unwrap();assert_eq!(s.entry.take(),Some(Ok(())));p.bulk_memory_operation(SIZE,&mut s.entry).unwrap();assert_eq!(s.entry,Some(Ok(())));assert_eq!(p.phase.parts.values.as_slice(),&[Value::I32(584),Value::I32(584)]);});}
#[test] fn bm16_accounting_restore(){let _b=Bounds::new();fixture(true,None,|p|{let before=observed(p);op(p,SIZE).unwrap();assert_eq!(observed(p).reservations,before.reservations);assert_eq!(FRAME_OPERATION_BYTES.unwrap(),super::super::ACTIVE_BYTES+value_operations::VALUE_OPERATION_BYTES.unwrap()+control_operations::ACTIVE_BYTES+super::super::memory_operations::ACTIVE_BYTES+ACTIVE_BYTES+super::super::memory_growth_operations::ACTIVE_BYTES + super::super::host_runtime_import::ACTIVE_BYTES + super::super::call_dispatch::ACTIVE_BYTES.unwrap());assert_eq!(SwiftRunBudget::default().state_bytes,128*1024*1024);assert_eq!(SwiftRunBudget::default().combined_bytes,256*1024*1024);println!("BM_COMPONENT acceptedMemoryActive={} addedBulkActive={} completeEnvelope={}",super::super::memory_operations::ACTIVE_BYTES,ACTIVE_BYTES,FRAME_OPERATION_BYTES.unwrap());});}

#[test] fn cdr04_actual_pinned_bulk_pop_attribution(){let _b=Bounds::new();fixture(true,Some(BODY),|p|{push(p,&[Value::I32(0),Value::I32(0),Value::I32(1)]);p.phase.parts.frames[0].pc=3;let actual={let f=&p.phase.parts.frames[0];p.phase.parts.cache.view(&f.pin,p.phase.operation.control,Some(&*p.phase.operation.wasi)).unwrap().instructions[3]};hooks(Hooks{push_fault:5,..Hooks::default()});let mut s=storage();pinned(p,&mut s).unwrap();let failure=s.entry.unwrap().unwrap_err();assert_eq!((failure.stage,failure.function,failure.offset,failure.resource),(SwiftRunStage::Invocation,Some(34),Some(actual.offset),Some(SwiftRunResource::Values)));assert_eq!((failure.attempted,failure.limit),(1,0));assert!(p.cleanup.live_unreconciled);assert_eq!(p.phase.parts.values.len(),2);assert_eq!(p.phase.parts.memory[0],0);});}
